// Core entities with clear responsibilities
record Vehicle(String licensePlate, VehicleType type) {}

enum VehicleType { CAR, MOTORCYCLE, TRUCK }

class ParkingSpot {
    private final int spotNumber;
    private final VehicleType allowedType;
    private Vehicle parkedVehicle;

    public ParkingSpot(int spotNumber, VehicleType allowedType) {
        this.spotNumber = spotNumber;
        this.allowedType = allowedType;
    }

    public boolean isAvailable() {
        return parkedVehicle == null;
    }

    public boolean canFit(Vehicle vehicle) {
        return isAvailable() && vehicle.type() == allowedType;
    }

    public void parkVehicle(Vehicle vehicle) {
        if (!canFit(vehicle)) throw new IllegalStateException("Cannot park here");
        this.parkedVehicle = vehicle;
    }

    public Vehicle removeVehicle() {
        var vehicle = this.parkedVehicle;
        this.parkedVehicle = null;
        return vehicle; // Return for billing
    }
}

class ParkingFloor {
    private final int floorNumber;
    private final List<ParkingSpot> spots;

    public ParkingFloor(int floorNumber, List<ParkingSpot> spots) {
        this.floorNumber = floorNumber;
        this.spots = spots;
    }

    public Optional<ParkingSpot> findAvailableSpot(VehicleType type) {
        return spots.stream()
            .filter(spot -> spot.canFit(new Vehicle("", type)))
            .findFirst();
    }
}

// Step 2: Identify entities - ATM, Account, Card, Transaction
record Card(String cardNumber, String pin) {}

class Account {
    private final String accountNumber;
    private double balance;

    public Account(String accountNumber, double initialBalance) {
        this.accountNumber = accountNumber;
        this.balance = initialBalance;
    }

    public boolean withdraw(double amount) {
        if (amount > balance) return false;
        balance -= amount;
        return true;
    }

    public void deposit(double amount) {
        balance += amount;
    }

    public double getBalance() { return balance; }
}

// Step 3: Define responsibilities - ATM coordinates, Account manages money
class ATM {
    private final String atmId;
    private double cashAvailable;

    public ATM(String atmId, double cashAvailable) {
        this.atmId = atmId;
        this.cashAvailable = cashAvailable;
    }

    // Step 4: ATM HAS-A relationship with Account (association)
    public boolean dispenseCash(Account account, double amount) {
        if (amount > cashAvailable) return false;
        if (account.withdraw(amount)) {
            cashAvailable -= amount;
            return true;
        }
        return false;
    }
}

// Step 5: Could add Strategy pattern for different transaction types later

// S: Single Responsibility - each class has one job
class ParkingSpot {
    private Vehicle vehicle;
    private LocalDateTime entryTime;

    public void occupy(Vehicle v) {
        this.vehicle = v;
        this.entryTime = LocalDateTime.now();
    }

    public Duration getParkedDuration() {
        return Duration.between(entryTime, LocalDateTime.now());
    }
}

// O: Open/Closed - extend behavior via interface, don't modify
interface PricingStrategy {
    double calculateFee(Duration duration, VehicleType type);
}

class HourlyPricing implements PricingStrategy {
    public double calculateFee(Duration duration, VehicleType type) {
        long hours = duration.toHours();
        return hours * (type == VehicleType.TRUCK ? 10.0 : 5.0);
    }
}

class FlatRatePricing implements PricingStrategy {
    public double calculateFee(Duration duration, VehicleType type) {
        return 20.0; // Flat fee regardless of time
    }
}

// D: Depend on abstraction (PricingStrategy), not concrete class
class BillingService {
    private final PricingStrategy pricingStrategy;

    public BillingService(PricingStrategy strategy) {
        this.pricingStrategy = strategy; // DIP: injected dependency
    }

    public double generateBill(ParkingSpot spot, VehicleType type) {
        return pricingStrategy.calculateFee(spot.getParkedDuration(), type);
    }
}

// SINGLETON: One global ParkingLot instance
class ParkingLot {
    private static ParkingLot instance;
    private final List<ParkingFloor> floors;

    private ParkingLot() {
        this.floors = new ArrayList<>();
    }

    public static synchronized ParkingLot getInstance() {
        if (instance == null) {
            instance = new ParkingLot();
        }
        return instance;
    }
}

// STRATEGY: Interchangeable pricing algorithms
interface PricingStrategy {
    double calculate(Duration duration);
}

class WeekdayPricing implements PricingStrategy {
    public double calculate(Duration d) { return d.toHours() * 5.0; }
}

class WeekendPricing implements PricingStrategy {
    public double calculate(Duration d) { return d.toHours() * 3.0; }
}

class BillingService {
    private PricingStrategy strategy;

    public void setStrategy(PricingStrategy s) { this.strategy = s; }
    public double computeFee(Duration d) { return strategy.calculate(d); }
}

// FACTORY: Create different vehicle types
class VehicleFactory {
    public static Vehicle createVehicle(String type, String license) {
        return switch (type.toUpperCase()) {
            case "CAR" -> new Car(license);
            case "MOTORCYCLE" -> new Motorcycle(license);
            case "TRUCK" -> new Truck(license);
            default -> throw new IllegalArgumentException("Unknown type");
        };
    }
}
